-- Comentarios da CLT, lote 6 (arts. 223-A a 223-G, 224 a 253, com 235-A a 235-G, e 293 a 300). Autorizado pela Jessica em 21/10/2026.
-- Redigidos so a partir do texto do artigo e dos dispositivos filhos no banco (sem jurisprudencia ou doutrina).
-- Reverter: update legislacao set contexto=null, aplicacao_pratica=null where codigo='clt' and numero between 202 and 300;
update legislacao l set contexto=v.c, aplicacao_pratica=v.a
from (values
(223,'Art. 223-A','Dispositivos aplicáveis à reparação de dano extrapatrimonial trabalhista','Aplicam-se à reparação de danos de natureza extrapatrimonial decorrentes da relação de trabalho apenas os dispositivos do Título. O caput consta na fonte com as anotações "Vide ADI 6050", "Vide ADI 6069" e "Vide ADI 6082", e este comentário não afirma o seu resultado.'),
(223,'Art. 223-B','Conceito de dano extrapatrimonial','Causa dano de natureza extrapatrimonial a ação ou omissão que ofenda a esfera moral ou existencial da pessoa física ou jurídica, as quais são as titulares exclusivas do direito à reparação. O caput consta na fonte com as anotações "Vide ADI 6050", "Vide ADI 6069" e "Vide ADI 6082", e este comentário não afirma o seu resultado.'),
(223,'Art. 223-C','Bens juridicamente tutelados da pessoa física','A honra, a imagem, a intimidade, a liberdade de ação, a autoestima, a sexualidade, a saúde, o lazer e a integridade física são os bens juridicamente tutelados inerentes à pessoa física.'),
(223,'Art. 223-D','Bens juridicamente tutelados da pessoa jurídica','A imagem, a marca, o nome, o segredo empresarial e o sigilo da correspondência são bens juridicamente tutelados inerentes à pessoa jurídica.'),
(223,'Art. 223-E','Responsáveis pelo dano extrapatrimonial','São responsáveis pelo dano extrapatrimonial todos os que tenham colaborado para a ofensa ao bem jurídico tutelado, na proporção da ação ou da omissão.'),
(223,'Art. 223-F','Cumulação da reparação extrapatrimonial com danos materiais','A reparação por danos extrapatrimoniais pode ser pedida cumulativamente com a indenização por danos materiais decorrentes do mesmo ato lesivo. O § 1º dispõe que, havendo cumulação de pedidos, o juízo, ao proferir a decisão, discrimina os valores das indenizações a título de danos patrimoniais e das reparações por danos de natureza extrapatrimonial. O § 2º dispõe que a composição das perdas e danos, assim compreendidos os lucros cessantes e os danos emergentes, não interfere na avaliação dos danos extrapatrimoniais.'),
(223,'Art. 223-G','Critérios para apreciar o pedido de reparação extrapatrimonial','Ao apreciar o pedido, o juízo considera: a natureza do bem jurídico tutelado (inciso I); a intensidade do sofrimento ou da humilhação (inciso II); a possibilidade de superação física ou psicológica (inciso III); os reflexos pessoais e sociais da ação ou da omissão (inciso IV); a extensão e a duração dos efeitos da ofensa (inciso V); as condições em que ocorreu a ofensa ou o prejuízo moral (inciso VI); o grau de dolo ou culpa (inciso VII); a ocorrência de retratação espontânea (inciso VIII); o esforço efetivo para minimizar a ofensa (inciso IX); o perdão, tácito ou expresso (inciso X); a situação social e econômica das partes envolvidas (inciso XI); e o grau de publicidade da ofensa (inciso XII). O § 1º dispõe que, se julgar procedente o pedido, o juízo fixa a indenização a ser paga, a cada um dos ofendidos, em um dos parâmetros dos incisos I a IV, vedada a acumulação: ofensa de natureza leve, até três vezes o último salário contratual do ofendido (inciso I); média, até cinco vezes (inciso II); grave, até vinte vezes (inciso III); e gravíssima, até cinquenta vezes (inciso IV). O § 2º aplica os mesmos parâmetros, se o ofendido for pessoa jurídica, em relação ao salário contratual do ofensor, e o § 3º permite ao juízo elevar ao dobro o valor da indenização na reincidência entre partes idênticas. O caput e dispositivos filhos constam na fonte com anotações "Vide ADI 6050", "Vide ADI 6069", "Vide ADI 6082" e "Vide Processo 1004752-21.2020.5.02.0000", e este comentário não afirma o seu resultado.'),
(224,'','Duração do trabalho dos bancários','A duração normal do trabalho dos empregados em bancos, casas bancárias e Caixa Econômica Federal é de 6 (seis) horas contínuas nos dias úteis, com exceção dos sábados, perfazendo um total de 30 (trinta) horas de trabalho por semana. O § 1º dispõe que a duração normal fica compreendida entre sete e vinte e duas horas, assegurando-se ao empregado, no horário diário, um intervalo de quinze minutos para alimentação. O § 2º afasta as disposições do artigo dos que exercem funções de direção, gerência, fiscalização, chefia e equivalentes ou que desempenhem outros cargos de confiança, desde que o valor da gratificação atenda ao limite que o próprio parágrafo estabelece.'),
(225,'','Prorrogação da jornada dos bancários','A duração normal de trabalho dos bancários pode ser excepcionalmente prorrogada até 8 (oito) horas diárias, não excedendo 40 (quarenta) horas semanais, observados os preceitos gerais sobre a duração do trabalho.'),
(226,'','Regime de seis horas para empregados de portaria e limpeza dos bancos','O regime especial de 6 (seis) horas de trabalho também se aplica aos empregados de portaria e de limpeza, tais como porteiros, telefonistas de mesa, contínuos e serventes, empregados em bancos e casas bancárias. O parágrafo único determina que a direção de cada banco organize a escala de serviço do estabelecimento de maneira a haver empregados do quadro da portaria em função meia hora antes e até meia hora após o encerramento dos trabalhos, respeitado o limite que o parágrafo indica.'),
(227,'','Duração do trabalho dos operadores de telefonia, telegrafia e radiotelegrafia','Nas empresas que explorem o serviço de telefonia, telegrafia submarina ou subfluvial, de radiotelegrafia ou de radiotelefonia, fica estabelecida para os respectivos operadores a duração máxima de seis horas contínuas de trabalho por dia ou 36 (trinta e seis) horas semanais. O § 1º dispõe que, em caso de indeclinável necessidade, se os operadores forem obrigados a permanecer em serviço além do período normal, a empresa paga extraordinariamente o tempo excedente com acréscimo de 50%. O § 2º dispõe que o trabalho aos domingos, feriados e dias santos de guarda é considerado extraordinário e obedece, quanto à sua execução e remuneração, ao que dispuserem empregadores e empregados em acordo, ou os respectivos sindicatos, nos termos do parágrafo.'),
(228,'','Limite de velocidade na transmissão e recepção','Os operadores não podem trabalhar, de modo ininterrupto, na transmissão manual, bem como na recepção visual, auditiva, com escrita manual ou datilográfica, quando a velocidade for superior a 25 (vinte e cinco) palavras por minuto.'),
(229,'','Empregados sujeitos a horários variáveis','Para os empregados sujeitos a horários variáveis, fica estabelecida a duração máxima de 7 (sete) horas diárias de trabalho e 17 (dezessete) horas de folga, deduzindo-se deste tempo 20 (vinte) minutos para descanso, de cada um dos empregados, sempre que se verificar um esforço contínuo de mais de 3 (três) horas. O § 1º considera empregados sujeitos a horários variáveis, além dos operadores, cujas funções exijam classificação distinta, os que pertençam a seções de técnica, telefones, revisão, expedição, entrega e balcão. O § 2º dispõe que, quanto à execução e remuneração aos domingos, feriados e dias santos de guarda e às prorrogações de expediente, o trabalho desses empregados é regido pelo § 1º do art. 227.'),
(230,'','Revezamento de turmas e horários de refeição','A direção das empresas deve organizar as turmas de empregados, para a execução dos seus serviços, de maneira que prevaleça sempre o revezamento entre os que exercem a mesma função, quer em escalas diurnas, quer em noturnas. O § 1º permite aos empregados que exerçam a mesma função a troca de turmas entre si, desde que isso não importe em prejuízo dos serviços, cabendo ao chefe ou encarregado resolver sobre a oportunidade ou possibilidade dessa medida. O § 2º veda às empresas organizar horários que obriguem os empregados a fazer a refeição do almoço antes das 10 (dez) e depois das 13 (treze) horas e a de jantar antes das 16 (dezesseis) e depois das 19:30 (dezenove e trinta) horas.'),
(231,'','Exclusão dos operadores de radiotelegrafia embarcados','As disposições da Seção não abrangem o trabalho dos operadores de radiotelegrafia embarcados em navios ou aeronaves.'),
(232,'','Duração do trabalho dos músicos','É de seis horas a duração de trabalho dos músicos em teatro e congêneres. O parágrafo único dispõe que, toda vez que o trabalho contínuo em espetáculo ultrapassar seis horas, o tempo de duração excedente é pago com acréscimo de 25% (vinte e cinco por cento) sobre o salário da hora normal.'),
(233,'','Elevação da jornada dos músicos profissionais','A duração normal de trabalho dos músicos profissionais pode ser elevada até oito horas diárias, observados os preceitos gerais sobre duração do trabalho.'),
(234,'','Duração do trabalho dos operadores cinematográficos','A duração normal do trabalho dos operadores cinematográficos e seus ajudantes não excede seis horas diárias, assim distribuídas: 5 (cinco) horas consecutivas de trabalho em cabina, durante o funcionamento cinematográfico (alínea a); e 1 (um) período suplementar, até o máximo de 1 (uma) hora para limpeza, lubrificação dos aparelhos de projeção ou revisão de filmes (alínea b). O parágrafo único trata da remuneração adicional de 25% (vinte e cinco por cento) sobre o salário da hora normal e do intervalo de 2 (duas) horas para folga entre o período a que se refere a alínea b e o trabalho seguinte, nos termos do parágrafo.'),
(235,'','Trabalho cumulativo dos operadores cinematográficos em estabelecimentos noturnos','Nos estabelecimentos cujo funcionamento normal seja noturno, é facultado aos operadores cinematográficos e seus ajudantes, mediante acordo ou contrato coletivo de trabalho e com acréscimo de 25% (vinte e cinco por cento) sobre o salário da hora normal, executar o trabalho em sessões diurnas extraordinárias e, cumulativamente, nas noturnas, desde que isso se verifique até 3 (três) vezes por semana e entre as sessões diurnas e as noturnas haja o intervalo de 1 (uma) hora, no mínimo, de descanso. O § 1º dispõe que a duração do trabalho cumulativo não pode exceder 10 (dez) horas, e o § 2º exige que, em seguida a cada período de trabalho, haja intervalo de repouso de no mínimo 12 (doze) horas.'),
(235,'Art. 235-A','Aplicação da Seção ao motorista profissional empregado','Os preceitos especiais da Seção aplicam-se ao motorista profissional empregado de transporte rodoviário coletivo de passageiros (inciso I) e de transporte rodoviário de cargas (inciso II).'),
(235,'Art. 235-B','Deveres do motorista profissional empregado','São deveres do motorista profissional empregado: estar atento às condições de segurança do veículo (inciso I); conduzir o veículo com perícia, prudência, zelo e com observância aos princípios de direção defensiva (inciso II); respeitar a legislação de trânsito e, em especial, as normas relativas ao tempo de direção e de descanso controlado e registrado na forma do previsto no art. 67-E do Código de Trânsito Brasileiro (inciso III); zelar pela carga transportada e pelo veículo (inciso IV); colocar-se à disposição dos órgãos públicos de fiscalização na via pública (inciso V); e submeter-se a exames toxicológicos com janela de detecção mínima de 90 (noventa) dias e a programa de controle de uso de droga e de bebida alcoólica, instituído pelo empregador, com sua ampla ciência, com a periodicidade que o inciso fixa (inciso VII). O parágrafo único dispõe que a recusa do empregado em submeter-se ao teste ou ao programa previstos no inciso VII é considerada infração disciplinar, passível de penalização nos termos da lei.'),
(235,'Art. 235-C','Jornada de trabalho do motorista profissional','A jornada diária de trabalho do motorista profissional é de 8 (oito) horas, admitindo-se a sua prorrogação por até 2 (duas) horas extraordinárias ou, mediante previsão em convenção ou acordo coletivo, por até 4 (quatro) horas extraordinárias. O § 1º considera trabalho efetivo o tempo em que o motorista empregado estiver à disposição do empregador, excluídos os intervalos para refeição, repouso e descanso e o tempo de espera. O § 2º assegura intervalo mínimo de 1 (uma) hora para refeição, e o § 3º assegura 11 (onze) horas de descanso dentro do período de 24 (vinte e quatro) horas, facultados o seu fracionamento e a coincidência com os períodos de parada obrigatória na condução do veículo. O § 5º dispõe que as horas extraordinárias são pagas com o acréscimo estabelecido na Constituição Federal ou compensadas na forma do § 2º do art. 59, e o § 6º aplica à hora de trabalho noturno o art. 73. Os §§ 8º a 12 tratam do tempo de espera: o § 8º define as horas em que o motorista fica aguardando carga ou descarga do veículo nas dependências do embarcador ou do destinatário, o § 9º determina a indenização dessas horas na proporção de 30% (trinta por cento) do salário-hora normal, o § 10 dispõe que o tempo de espera não prejudica o direito à remuneração correspondente ao salário-base diário, e o § 12 trata das movimentações necessárias do veículo durante a espera. O § 13 dispõe que, salvo previsão contratual, a jornada do motorista empregado não tem horário fixo de início, de final ou de intervalos. O § 14 atribui ao empregado a responsabilidade pela guarda, preservação e exatidão das informações contidas nas anotações em diário de bordo, papeleta ou ficha de trabalho externo, ou no registrador instantâneo inalterável de velocidade e tempo, e o § 15 permite o envio dos dados a distância, a critério do empregador. O § 16 aplica o artigo ao ajudante empregado nas operações em que acompanhe o motorista. Os §§ 1º e 9º constam na fonte com a anotação "Vide ADI 5322", e este comentário não afirma o seu resultado.'),
(235,'Art. 235-D','Repouso nas viagens de longa distância','Nas viagens de longa distância com duração superior a 7 (sete) dias, o repouso semanal é de 24 (vinte e quatro) horas por semana ou fração trabalhada, sem prejuízo do intervalo de repouso diário de 11 (onze) horas, totalizando 35 (trinta e cinco) horas, usufruído no retorno do motorista à base (matriz ou filial) ou ao seu domicílio, salvo se a empresa oferecer condições adequadas para o efetivo gozo do referido repouso. O § 1º permite o fracionamento do repouso semanal em 2 (dois) períodos, sendo um deles de, no mínimo, 30 (trinta) horas ininterruptas. O § 2º limita a cumulatividade de descansos semanais ao número de 3 (três) descansos consecutivos. O § 3º dispensa do serviço o motorista que ficar com o veículo parado após o cumprimento da jornada normal ou das horas extraordinárias, exceto se for expressamente autorizada a sua permanência, nos termos do parágrafo. O § 4º dispõe que não é jornada de trabalho, nem enseja remuneração, o período em que o motorista empregado ou o ajudante ficarem espontaneamente no veículo usufruindo dos intervalos de repouso. O § 5º trata do empregador que adotar 2 (dois) motoristas trabalhando no mesmo veículo, caso em que o tempo de repouso pode ser feito com o veículo em movimento, assegurado o repouso mínimo de 6 (seis) horas consecutivas fora do veículo em alojamento. O § 7º trata do motorista que tenha de acompanhar o veículo transportado por qualquer meio onde ele siga embarcado, e o § 8º permite regras conforme a especificidade da operação para o transporte de cargas vivas, perecíveis e especiais em longa distância ou em território estrangeiro. O caput e o § 2º constam na fonte com a anotação "Vide ADI 5322", e este comentário não afirma o seu resultado.'),
(235,'Art. 235-E','Normas para o transporte de passageiros','Para o transporte de passageiros, são observados os seguintes dispositivos: é facultado o fracionamento do intervalo de condução do veículo previsto no Código de Trânsito Brasileiro, em períodos de no mínimo 5 (cinco) minutos (inciso I); é assegurado ao motorista intervalo mínimo de 1 (uma) hora para refeição, podendo ser fracionado em 2 (dois) períodos e coincidir com o tempo de parada obrigatória na condução do veículo (inciso II); e, nos casos em que o empregador adotar 2 (dois) motoristas no curso da mesma viagem, o descanso pode ser feito com o veículo em movimento, respeitando-se os horários de jornada de trabalho, nos termos do inciso III.'),
(235,'Art. 235-F','Jornada de doze horas por trinta e seis de descanso do motorista','Convenção e acordo coletivo podem prever jornada especial de 12 (doze) horas de trabalho por 36 (trinta e seis) horas de descanso para o trabalho do motorista profissional empregado em regime de compensação.'),
(235,'Art. 235-G','Remuneração do motorista por distância, tempo ou produtos transportados','É permitida a remuneração do motorista em função da distância percorrida, do tempo de viagem ou da natureza e quantidade de produtos transportados, inclusive mediante oferta de comissão ou qualquer outro tipo de vantagem, desde que essa remuneração ou comissionamento não comprometa a segurança da rodovia e da coletividade ou possibilite a violação das normas previstas na Lei.'),
(236,'','Âmbito do serviço ferroviário','No serviço ferroviário, considerado este o de transporte em estradas de ferro abertas ao tráfego público, compreendendo a administração, construção, conservação e remoção das vias férreas e seus edifícios, obras de arte, material rodante, instalações complementares e acessórias, bem como o serviço de tráfego, de telegrafia, telefonia e funcionamento de todas as instalações ferroviárias, aplicam-se os preceitos especiais constantes da Seção.'),
(237,'','Categorias do pessoal ferroviário','O pessoal a que se refere o artigo antecedente fica dividido nas seguintes categorias: funcionários de alta administração, chefes e ajudantes de departamentos e seções, engenheiros residentes, chefes de depósitos, inspetores e demais empregados que exercem funções administrativas ou fiscalizadoras (alínea a); pessoal que trabalhe em lugares ou trechos determinados e cujas tarefas requeiram atenção constante, pessoal de escritório, turmas de conservação e construção da via permanente, oficinas e estações principais (alínea b); das equipagens de trens em geral (alínea c); e pessoal cujo serviço é de natureza intermitente ou de pouca intensidade, embora com permanência prolongada nos locais de trabalho, vigias e pessoal das estações do interior (alínea d).'),
(238,'','Tempo de trabalho efetivo no serviço ferroviário','É computado como de trabalho efetivo todo o tempo em que o empregado estiver à disposição da estrada. O § 1º dispõe que, nos serviços efetuados pelo pessoal da categoria c, não é considerado como de trabalho efetivo o tempo gasto em viagens do local ou para o local de terminação e início dos mesmos serviços. O § 2º dispõe que, ao pessoal removido ou comissionado fora da sede, é contado como de trabalho normal e efetivo o tempo gasto em viagens, sem direito à percepção de horas extraordinárias. O § 3º trata das turmas de conservação da via permanente, cujo tempo efetivo de trabalho é contado desde a hora da saída da casa da turma até a hora em que cessar o serviço. O § 4º trata do pessoal da equipagem de trens. O § 5º dispõe que o tempo concedido para refeição não se computa como de trabalho efetivo, senão para o pessoal da categoria c, quando as refeições forem tomadas em viagem ou nas estações durante as paradas. O § 6º trata das turmas encarregadas da conservação de obras de arte, linhas telegráficas ou telefônicas e edifícios, cujo tempo de viagem para o local do serviço não é contado como de trabalho efetivo, nos termos do parágrafo.'),
(239,'','Prorrogação do trabalho do pessoal da categoria c','Para o pessoal da categoria c, a prorrogação do trabalho independe de acordo ou contrato coletivo, não podendo, entretanto, exceder 12 (doze) horas, pelo que as empresas organizam, sempre que possível, os serviços de equipagens de trens com destacamentos nos trechos das linhas, de modo a ser observada a duração normal de oito horas de trabalho. O § 1º exige repouso de 10 (dez) horas contínuas, no mínimo, depois de cada jornada, observando-se o descanso semanal. O § 2º trata da ajuda de custo concedida ao pessoal da equipagem de trens quando a empresa não fornecer alimentação em viagem e hospedagem no destino. O § 3º dispõe que as escalas sejam organizadas de modo que não caiba a qualquer empregado, quinzenalmente, um total de horas de serviço noturno superior às de serviço diurno, e o § 4º determina o registro dos períodos de trabalho em cadernetas especiais, que ficam sempre em poder do empregado, de acordo com o modelo aprovado pelo Ministro do Trabalho. O caput consta na fonte com a anotação "Vide Decreto-Lei nº 6.361, de 1944", e este comentário não afirma o seu resultado.'),
(240,'','Elevação excepcional da duração do trabalho ferroviário','Nos casos de urgência ou de acidente, capazes de afetar a segurança ou regularidade do serviço, a duração do trabalho pode ser excepcionalmente elevada a qualquer número de horas, incumbindo à Estrada zelar pela incolumidade dos seus empregados e pela possibilidade de revezamento de turmas, assegurando ao pessoal um repouso correspondente e comunicando a ocorrência ao Ministério do Trabalho, Indústria e Comércio, dentro de 10 (dez) dias da sua verificação. O parágrafo único dispõe que, nesses casos, a recusa, sem causa justificada, por parte de qualquer empregado, à execução de serviço extraordinário é considerada falta grave.'),
(241,'','Remuneração das horas extras no serviço ferroviário','As horas excedentes das do horário normal de oito horas são pagas como serviço extraordinário na seguinte base: as duas primeiras com acréscimo de 25% (vinte e cinco por cento) sobre o salário-hora normal, as duas subsequentes com adicional de 50% (cinquenta por cento) e as restantes com adicional de 75% (setenta e cinco por cento). O parágrafo único trata do pessoal da categoria c, para o qual a primeira hora é majorada de 25%, a segunda hora é paga com acréscimo de 50% e as duas subsequentes com o de 60%. O caput consta na fonte com a anotação "Vide Decreto-Lei nº 6.361, de 1944", e este comentário não afirma o seu resultado.'),
(242,'','Cômputo das frações de meia hora','As frações de meia hora superiores a 10 (dez) minutos são computadas como meia hora.'),
(243,'','Empregados de estações do interior','Para os empregados de estações do interior, cujo serviço for de natureza intermitente ou de pouca intensidade, não se aplicam os preceitos gerais sobre duração do trabalho, sendo-lhes, entretanto, assegurado o repouso contínuo de dez horas, no mínimo, entre dois períodos de trabalho e descanso semanal.'),
(244,'','Extranumerários, sobreaviso e prontidão nas estradas de ferro','As estradas de ferro podem ter empregados extranumerários, de sobreaviso e de prontidão, para executarem serviços imprevistos ou para substituições de outros empregados que faltem à escala organizada. O § 1º considera extranumerário o empregado não efetivo, candidato à efetivação, que se apresentar normalmente ao serviço, embora só trabalhe quando for necessário, e dispõe que ele só recebe os dias de trabalho efetivo. O § 2º considera de sobreaviso o empregado efetivo que permanecer em sua própria casa, aguardando a qualquer momento o chamado para o serviço, e fixa a escala máxima de vinte e quatro horas. O § 3º considera de prontidão o empregado que ficar nas dependências da estrada, aguardando ordens, com escala de no máximo doze horas, e as horas de prontidão são contadas, para todos os efeitos, à razão de 2/3 (dois terços), nos termos do parágrafo. O § 4º trata da hipótese de haver facilidade de alimentação no estabelecimento ou dependência, caso em que as doze horas de prontidão podem ser contínuas.'),
(245,'','Horário dos cabineiros','O horário normal de trabalho dos cabineiros nas estações de tráfego intenso não excede 8 (oito) horas e deve ser dividido em 2 (dois) turnos com intervalo não inferior a 1 (uma) hora de repouso, não podendo nenhum turno ter duração superior a 5 (cinco) horas, com um período de descanso entre 2 (duas) jornadas de trabalho de 14 (quatorze) horas consecutivas.'),
(246,'','Horário dos operadores telegrafistas','O horário de trabalho dos operadores telegrafistas nas estações de tráfego intenso não excede 6 (seis) horas diárias.'),
(247,'','Classificação das estações ferroviárias','As estações principais, estações de tráfego intenso e estações do interior são classificadas para cada empresa pelo Departamento Nacional de Estradas de Ferro.'),
(248,'','Duração do trabalho dos tripulantes','Entre as horas 0 (zero) e 24 (vinte e quatro) de cada dia civil, o tripulante pode ser conservado em seu posto durante 8 (oito) horas, quer de modo contínuo, quer de modo intermitente. O § 1º dispõe que a exigência do serviço contínuo ou intermitente fica a critério do comandante e, neste último caso, nunca por período menor que 1 (uma) hora. O § 2º dispõe que os serviços de quarto nas máquinas, passadiço, vigilância e outros que, consoante parecer médico, possam prejudicar a saúde do tripulante são executados por períodos não maiores e com intervalos não menores de 4 (quatro) horas.'),
(249,'','Trabalho extraordinário dos tripulantes','Todo o tempo de serviço efetivo, excedente de 8 (oito) horas, ocupado na forma do artigo anterior, é considerado de trabalho extraordinário, sujeito à compensação a que se refere o art. 250, exceto se se tratar de trabalho executado: em virtude de responsabilidade pessoal do tripulante e no desempenho de funções de direção (alínea a); na iminência de perigo, para salvaguarda ou defesa da embarcação, dos passageiros ou da carga, a juízo exclusivo do comandante ou do responsável pela segurança a bordo (alínea b); por motivo de manobras ou fainas gerais que reclamem a presença, em seus postos, de todo o pessoal de bordo (alínea c); e na navegação lacustre e fluvial, nas hipóteses que a alínea d indica (alínea d). O § 1º dispõe que o trabalho executado aos domingos e feriados é considerado extraordinário, salvo se se destinar ao serviço de quartos e vigilância, movimentação das máquinas e aparelhos de bordo, limpeza e higiene da embarcação, preparo de alimentação da equipagem e dos passageiros, serviço pessoal destes e socorros de urgência (alínea a), ou ao fim da navegação ou das manobras para a entrada ou saída de portos, atracação, desatracação, embarque ou desembarque de carga e passageiros (alínea b). O § 2º dispõe que não excede 30 (trinta) horas semanais o serviço extraordinário prestado para o tráfego nos portos.'),
(250,'','Compensação das horas extraordinárias dos tripulantes','As horas de trabalho extraordinário são compensadas, segundo a conveniência do serviço, por descanso em período equivalente no dia seguinte ou no subsequente dentro das do trabalho normal, ou no fim da viagem, ou pelo pagamento do salário correspondente. O parágrafo único dispõe que as horas extraordinárias de trabalho são indivisíveis, computando-se a fração de hora como hora inteira.'),
(251,'','Livros de bordo para horas extraordinárias e transgressões','Em cada embarcação há um livro em que são anotadas as horas extraordinárias de trabalho de cada tripulante, e outro, do qual constam, devidamente circunstanciadas, as transgressões dos mesmos tripulantes. O parágrafo único dispõe que os livros obedecem a modelos organizados pelo Ministério do Trabalho, Indústria e Comércio, são escriturados em dia pelo comandante da embarcação e ficam sujeitos às formalidades que o parágrafo indica.'),
(252,'','Recurso do tripulante','Qualquer tripulante que se julgue prejudicado por ordem emanada de superior hierárquico pode interpor recurso, em termos, perante a Delegacia do Trabalho Marítimo, por intermédio do respectivo comandante, o qual deve encaminhá-lo com a respectiva informação dentro de 5 (cinco) dias, contados de sua chegada ao porto.'),
(253,'','Repouso para o trabalho em câmaras frigoríficas','Para os empregados que trabalham no interior das câmaras frigoríficas e para os que movimentam mercadorias do ambiente quente ou normal para o frio e vice-versa, depois de 1 (uma) hora e 40 (quarenta) minutos de trabalho contínuo, é assegurado um período de 20 (vinte) minutos de repouso, computado esse intervalo como de trabalho efetivo. O parágrafo único considera artificialmente frio, para os fins do artigo, o que for inferior, nas primeira, segunda e terceira zonas climáticas do mapa oficial do Ministério do Trabalho, Indústria e Comércio, ao limite de temperatura que o parágrafo fixa.'),
(293,'','Duração do trabalho no subsolo das minas','A duração normal do trabalho efetivo para os empregados em minas no subsolo não excede 6 (seis) horas diárias ou 36 (trinta e seis) semanais.'),
(294,'','Tempo da boca da mina ao local de trabalho','O tempo despendido pelo empregado da boca da mina ao local do trabalho e vice-versa é computado para o efeito de pagamento do salário.'),
(295,'','Elevação da duração do trabalho no subsolo','A duração normal do trabalho efetivo no subsolo pode ser elevada até 8 (oito) horas diárias ou 48 (quarenta e oito) semanais, mediante acordo escrito entre empregado e empregador ou contrato coletivo de trabalho, sujeita essa prorrogação à prévia licença da autoridade competente em matéria de higiene do trabalho. O parágrafo único dispõe que a duração normal do trabalho efetivo no subsolo pode ser inferior a 6 (seis) horas diárias, por determinação da autoridade de que trata o artigo, tendo em vista condições locais de insalubridade.'),
(296,'','Remuneração da hora prorrogada no subsolo','A remuneração da hora prorrogada é, no mínimo, 25% (vinte e cinco por cento) superior à da hora normal e deve constar do acordo ou contrato coletivo de trabalho.'),
(297,'','Alimentação do empregado no subsolo','Ao empregado no subsolo é fornecida, pelas empresas exploradoras de minas, alimentação adequada à natureza do trabalho, de acordo com as instruções estabelecidas pelo Serviço de Alimentação da Previdência Social e aprovadas pelo Ministério do Trabalho, Indústria e Comércio.'),
(298,'','Pausa de repouso nos trabalhos de subsolo','Em cada período de 3 (três) horas consecutivas de trabalho, é obrigatória uma pausa de 15 (quinze) minutos para repouso, a qual é computada na duração normal de trabalho efetivo.'),
(299,'','Comunicação de acontecimentos que comprometam a vida ou a saúde','Quando nos trabalhos de subsolo ocorrerem acontecimentos que possam comprometer a vida ou a saúde do empregado, a empresa deve comunicar o fato imediatamente à autoridade regional do trabalho, do Ministério do Trabalho, Indústria e Comércio.'),
(300,'','Transferência do subsolo para a superfície por motivo de saúde','Sempre que, por motivo de saúde, for necessária a transferência do empregado, a juízo da autoridade competente em matéria de segurança e de medicina do trabalho, dos serviços no subsolo para os de superfície, a empresa é obrigada a realizar essa transferência, assegurando ao transferido a remuneração atribuída ao trabalhador de superfície em serviço equivalente, respeitada a capacidade profissional do interessado. O parágrafo único dispõe que, no caso de recusa do empregado em atender a essa transferência, é ouvida a autoridade competente em matéria de higiene e segurança do trabalho, que decide a respeito.')
) as v(n,t,c,a)
where l.codigo='clt' and l.numero=v.n and coalesce(l.titulo,'')=v.t and l.paragrafo is null and l.inciso is null and l.vigente and l.texto ~ '^Art';
